(function () {
  'use strict';
  window.QUESTION_BANK = Object.assign(window.QUESTION_BANK || {}, {"reference-skills-sub-heading":{"title":"Sub-heading","topic":"Reference Skills / Misc.","questions":[{"id":"reference-skills-sub-heading-q0001","version":3,"contentHash":"sha256:2a3073a8955b12e0ec0e3d3772330b4bfbbf509e8735cd87ca34864a27af2b3f","question":"What is the purpose of a sub-heading?","choices":["To decorate the page","To introduce a new section or topic","To end the chapter","To list the author"],"correct":1,"explanation":{"correct":"Answer: To introduce a new section or topic. Sub-headings act as labels for different parts of a text, helping the reader understand the main idea of the section that follows.","incorrect":[{"choice":"To decorate the page","category":"misunderstanding text features","reason":"While sub-headings can make a page look organized, their primary job is to provide information and structure, not just to act as decoration."},"",{"choice":"To end the chapter","category":"confusing text structure","reason":"Text that ends a chapter is usually a summary or a concluding paragraph. Sub-headings appear throughout the text to guide the reader through specific topics."},{"choice":"To list the author","category":"misidentifying author credit","reason":"The author's name is typically found on the title page or at the beginning of an article. Sub-headings are used to divide the actual content into smaller, readable sections."}]},"studyAid":{"definition":"A sub-heading is a title for a smaller section of text that explains what the upcoming paragraphs will be about.","example":"In a book about space, 'The Solar System' and 'Exploring Mars' would be sub-headings that help you find specific facts.","strategyClue":"Look at the bold words above a paragraph and ask yourself, 'If I were looking for information on this topic, would this title help me find it?'","link":"https://www.readingrockets.org/topics/comprehension/articles/using-text-features-support-comprehension","linkText":"Reading Rockets - Text Features"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["reference skills","research skills","text features"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"reference-skills-sub-heading","sequence":1,"skillIds":["reference-skills.reference-research"],"standardIds":["W.3-6.7-8"]}},{"id":"reference-skills-sub-heading-q0002","version":3,"contentHash":"sha256:5db658744b9daeac410addc3d58af8bf0f06e8afd5f725ae2c31eec0369bd425","question":"Where do sub-headings usually appear?","choices":["At the very bottom of the page","Before a new section begins","Only in the table of contents","Inside footnotes"],"correct":1,"explanation":{"correct":"Answer: Before a new section begins. Sub-headings serve as titles for specific parts of a text, acting as signposts to help the reader know exactly what the upcoming paragraph or section is about.","incorrect":[{"choice":"At the very bottom of the page","category":"Incorrect text placement","reason":"Information at the bottom of the page is usually a footer or page number. Sub-headings are placed above the text they describe, not at the bottom of the page."},"",{"choice":"Only in the table of contents","category":"Restricted location error","reason":"While sub-headings are listed in the table of contents, they appear throughout the body of the book as well to help organize the content as you read."},{"choice":"Inside footnotes","category":"Misidentified text feature","reason":"Footnotes are small notes found at the bottom of a page that provide extra information or citations. They are not used to label or organize new sections."}]},"studyAid":{"definition":"A sub-heading is a short phrase or title that introduces a new section of text to show what the upcoming information will cover.","example":"In a book about space, a sub-heading might be 'The Planets' or 'How Stars Are Born' before those specific sections start.","strategyClue":"Imagine you are writing your own non-fiction book. Where would you place a label so that a reader knows the topic is about to change? Think about where you look to see if a paragraph is starting a new idea.","link":"https://www.readingrockets.org/topics/comprehension/articles/using-text-features-support-comprehension","linkText":"Reading Rockets - Text Features"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["reference skills","research skills","text features"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"reference-skills-sub-heading","sequence":2,"skillIds":["reference-skills.reference-research"],"standardIds":["W.3-6.7-8"]}},{"id":"reference-skills-sub-heading-q0003","version":3,"contentHash":"sha256:0faf1ed3b803043cb179da6d2962afeab2fbfd7f3580242bb6d45d5abac103b1","question":"Which is a sub-heading?","choices":["The title of the book","A smaller heading inside a chapter","The author's name","The page number"],"correct":1,"explanation":{"correct":"Answer: A smaller heading inside a chapter. Sub-headings act as mini-titles that organize specific sections of text within a larger chapter or article.","incorrect":[{"choice":"The title of the book","category":"major text feature","reason":"The title identifies the whole book, whereas a sub-heading only identifies a specific, smaller section of content."},"",{"choice":"The author's name","category":"incorrect identifying feature","reason":"The author's name tells you who wrote the book, not what information is contained within a specific section of the text."},{"choice":"The page number","category":"navigational text feature","reason":"Page numbers are used to help you locate your place in the book, while sub-headings are used to label the topics being discussed."}]},"studyAid":{"definition":"A sub-heading is a title for a smaller part of a text that helps readers understand what the next few paragraphs will be about.","example":"Chapter: 'Insects' / Sub-heading: 'Types of Bees'; Chapter: 'Planets' / Sub-heading: 'The Rings of Saturn'","strategyClue":"Ask yourself: 'Does this label describe the entire book, or just a small part of it?' Sub-headings always focus on a specific, narrow topic.","link":"https://www.readingrockets.org/topics/comprehension/articles/using-text-features-support-comprehension","linkText":"Reading Rockets - Text Features"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["reference skills","research skills","text features"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"reference-skills-sub-heading","sequence":3,"skillIds":["reference-skills.reference-research"],"standardIds":["W.3-6.7-8"]}},{"id":"reference-skills-sub-heading-q0004","version":3,"contentHash":"sha256:c148e115c5fbeff58e7b869bce6dac8fff3560c628b780af147603c1f963936e","question":"Why are sub-headings helpful?","choices":["They make the book longer.","They help readers locate information quickly.","They replace pictures.","They hide important facts."],"correct":1,"explanation":{"correct":"Answer: They help readers locate information quickly. Sub-headings act as signposts that organize a text, allowing readers to scan and find specific topics without reading every single word.","incorrect":[{"choice":"They make the book longer.","category":"incorrect text feature function","reason":"Sub-headings organize content rather than adding length. Adding extra words is what makes a book longer, not the organizational labels."},"",{"choice":"They replace pictures.","category":"incorrect text feature function","reason":"Sub-headings are text, not images. Pictures and sub-headings often work together to help you understand the information, but one does not replace the other."},{"choice":"They hide important facts.","category":"incorrect text feature function","reason":"Sub-headings actually do the opposite of hiding information! They act like a map to highlight where the important facts are located on the page."}]},"studyAid":{"definition":"Sub-headings are short phrases or titles used to break up long sections of text into smaller, related topics.","example":"In a book about space, a sub-heading might be 'The Planets' or 'How Rockets Fly'.","strategyClue":"Think about what you do when you are in a hurry and looking for one specific answer in a textbook; consider how titles above paragraphs guide your eyes to the right section.","link":"https://www.readingrockets.org/topics/comprehension/articles/using-text-features-support-comprehension","linkText":"Reading Rockets - Text Features"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["reference skills","research skills","text features"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"reference-skills-sub-heading","sequence":4,"skillIds":["reference-skills.reference-research"],"standardIds":["W.3-6.7-8"]}},{"id":"reference-skills-sub-heading-q0005","version":3,"contentHash":"sha256:0f119a844156e4e6cf200d70c2afbd493c42a45df81e41a4baba8fc12ac19d09","question":"Which text feature is MOST like a sub-heading?","choices":["Index","Glossary","Heading","Bibliography"],"correct":2,"explanation":{"correct":"Answer: Heading. A heading introduces a large section of text, while a sub-heading breaks that section down into smaller, specific topics. Both act as titles to organize information.","incorrect":[{"choice":"Index","category":"reference tool","reason":"An index is a list of keywords and page numbers found at the back of a book. It helps you find specific information, unlike a heading which organizes content."},{"choice":"Glossary","category":"vocabulary tool","reason":"A glossary is a mini-dictionary that defines hard words used in the text. It does not act as a title or a way to organize sections like a sub-heading does."},"",{"choice":"Bibliography","category":"source list","reason":"A bibliography is a list of books or websites the author used for research. It provides evidence for the writing, not structure for the text itself."}]},"studyAid":{"definition":"Text features are tools that help readers understand information by organizing it visually. Headings and sub-headings act as guideposts to show you what a section of text is about.","example":"Chapter Title: Space Exploration; Heading: The Moon Landing; Sub-heading: Walking on the Surface.","strategyClue":"Think about the purpose of the feature: is it a label for a part of the content, or is it a tool for finding specific definitions or extra references?","link":"https://www.readingrockets.org/topics/comprehension/articles/using-text-features-support-comprehension","linkText":"Reading Rockets - Text Features"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["reference skills","research skills","text features"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"reference-skills-sub-heading","sequence":5,"skillIds":["reference-skills.reference-research"],"standardIds":["W.3-6.7-8"]}},{"id":"reference-skills-sub-heading-q0006","version":3,"contentHash":"sha256:df9988d6d5d47e20cf1988108dd889f41e6a8473d52cdc1800d36981e3c146c1","question":"How is a sub-heading different from a title?","choices":["It is longer","It is smaller and divides sections within a chapter","It is only found in fiction","It is written in cursive"],"correct":1,"explanation":{"correct":"Answer: It is smaller and divides sections within a chapter. Sub-headings serve as labels for smaller parts of a text, helping readers see how information is organized into specific topics under the main title.","incorrect":[{"choice":"It is longer","category":"incorrect length comparison","reason":"Titles are usually the main name for the whole work and are longer or more descriptive, whereas sub-headings are short labels meant to grab attention for a specific section."},"",{"choice":"It is only found in fiction","category":"misunderstood text features","reason":"Sub-headings are actually more common in non-fiction textbooks and informational articles to help organize facts, rather than in storybooks."},{"choice":"It is written in cursive","category":"irrelevant formatting choice","reason":"Whether text is written in cursive, print, bold, or italics is a style choice. A sub-heading's purpose is defined by its role in organizing content, not by the font style used."}]},"studyAid":{"definition":"A title names the entire piece of writing, while a sub-heading acts like a mini-title that tells you what one specific section of the text is about.","example":"Title: 'All About Planets'; Sub-heading: 'The Gas Giants'. Title: 'Baking Basics'; Sub-heading: 'Measuring Ingredients'.","strategyClue":"Ask yourself: 'Does this label introduce the entire book, or does it just organize a small part of a page?' Only the labels for smaller, specific sections count as sub-headings.","link":"https://www.readingrockets.org/topics/comprehension/articles/using-text-features-support-comprehension","linkText":"Reading Rockets - Text Features"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["reference skills","research skills","text features"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"reference-skills-sub-heading","sequence":6,"skillIds":["reference-skills.reference-research"],"standardIds":["W.3-6.7-8"]}},{"id":"reference-skills-sub-heading-q0007","version":3,"contentHash":"sha256:1ca8560fbc2e259412e508087eafbb6834f06994575489b678455c52ac963314","question":"In a chapter about weather, which would be a sub-heading?","choices":["Weather","Chapter 3","Thunderstorms","By John Smith"],"correct":2,"explanation":{"correct":"Answer: Thunderstorms. Sub-headings should be specific topics that fall under the main subject of the chapter, like different types of weather.","incorrect":[{"choice":"Weather","category":"Main topic vs subheading","reason":"This is the main title or subject of the entire chapter, not a specific part of it. A sub-heading should be a narrower topic found inside the chapter."},{"choice":"Chapter 3","category":"Structural heading","reason":"This tells the reader where they are in the book, but it does not describe the specific information or content within that section."},"",{"choice":"By John Smith","category":"Author attribution","reason":"This is the name of the person who wrote the book. It belongs on the cover or title page, not as a sub-heading describing the weather."}]},"studyAid":{"definition":"A sub-heading acts like a mini-title that tells you exactly what a specific section of a chapter is about.","example":"Main Title: The Solar System. Sub-headings: The Sun, The Eight Planets, Moon Phases.","strategyClue":"Look at the main topic, then ask yourself which option acts as a smaller 'part' or 'category' that fits inside that bigger topic.","link":"https://www.readingrockets.org/topics/comprehension/articles/using-text-features-support-comprehension","linkText":"Reading Rockets - Text Features"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["reference skills","research skills","text features"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"reference-skills-sub-heading","sequence":7,"skillIds":["reference-skills.reference-research"],"standardIds":["W.3-6.7-8"]}},{"id":"reference-skills-sub-heading-q0008","version":3,"contentHash":"sha256:bffea18a9ddb34e13a43094713cb729fa6d9b87db944e60448ad3edf0c5bc6fb","question":"Which is NOT a function of sub-headings?","choices":["Organizing information","Showing page numbers","Previewing content","Breaking up long text"],"correct":1,"explanation":{"correct":"Answer: Showing page numbers. Sub-headings are used to organize topics within a text. Page numbers are typically found in the footer, header, or table of contents, not as a function of the headings themselves.","incorrect":[{"choice":"Organizing information","category":"text feature purpose","reason":"This is a primary function of sub-headings! They act as labels to group related paragraphs and details under a clear topic."},"",{"choice":"Previewing content","category":"text feature purpose","reason":"This is a correct use of sub-headings. Readers scan them before reading to understand what the upcoming section will be about."},{"choice":"Breaking up long text","category":"text feature purpose","reason":"This is a correct function. Sub-headings create white space and give the reader's eyes a break, making large blocks of text easier to read."}]},"studyAid":{"definition":"Sub-headings are titles for smaller sections of a text that help readers understand the structure and topic of the information that follows.","example":"A recipe might have sub-headings like 'Ingredients', 'Equipment', and 'Instructions'.","strategyClue":"Think about what a heading actually does visually: does it point to the location of the page, or does it name the subject you are about to read about?","link":"https://www.readingrockets.org/topics/comprehension/articles/using-text-features-support-comprehension","linkText":"Reading Rockets - Text Features"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["reference skills","research skills","text features"],"feedbackFocus":"spot the exception, then explain why the other choices follow the rule","estimatedTimeSeconds":35,"reviewPriority":"high","sourceSet":"reference-skills-sub-heading","sequence":8,"skillIds":["reference-skills.reference-research"],"standardIds":["W.3-6.7-8"]}},{"id":"reference-skills-sub-heading-q0009","version":3,"contentHash":"sha256:22e628f550fd4d41a3cc10627ba3466ec8d6bdaf0f2894135c5927a8c5cd364a","question":"What do bold sub-headings signal to a reader?","choices":["A new character is introduced","A new topic or section is starting","The book is ending","A quiz is coming"],"correct":1,"explanation":{"correct":"Answer: A new topic or section is starting. Sub-headings act like a map for the reader, clearly labeling the main idea of the section that follows.","incorrect":[{"choice":"A new character is introduced","category":"Incorrect text feature purpose","reason":"Sub-headings organize topics, not characters. Authors typically introduce new characters within the paragraphs of the story or chapter."},"",{"choice":"The book is ending","category":"Misinterpreting text structure","reason":"The end of a book is usually marked by the conclusion or a final chapter title, not by sub-headings, which are used throughout the text to organize information."},{"choice":"A quiz is coming","category":"Incorrect text feature purpose","reason":"Sub-headings are used to help readers understand the information in the book. They are not intended to signal that a test or quiz is about to happen."}]},"studyAid":{"definition":"Sub-headings are bold, short titles placed above sections of text to help readers identify the main topic of that section.","example":"In a book about space, a sub-heading might say 'The Sun' before a section describing our solar system.","strategyClue":"Look at the sub-heading as a label on a folder. Ask yourself, 'If I only read the section under this label, what would I be learning about?'","link":"https://www.readingrockets.org/topics/comprehension/articles/using-text-features-support-comprehension","linkText":"Reading Rockets - Text Features"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["reference skills","research skills","text features"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"reference-skills-sub-heading","sequence":9,"skillIds":["reference-skills.reference-research"],"standardIds":["W.3-6.7-8"]}},{"id":"reference-skills-sub-heading-q0010","version":3,"contentHash":"sha256:bef5f816a5221f42749c607d61929179ef6834bb35aa651eb7de665fb2aeeac3","question":"Where would you find sub-headings?","choices":["Only in novels","Only in science books","In textbooks, articles, and many nonfiction books","Only in comic books"],"correct":2,"explanation":{"correct":"Answer: In textbooks, articles, and many nonfiction books. Sub-headings are used to organize information and help readers navigate topics, which is common in factual or educational writing.","incorrect":[{"choice":"Only in novels","category":"Incorrect text type","reason":"Novels are usually written in chapters without sub-headings because they follow a continuous narrative story rather than breaking up factual topics."},{"choice":"Only in science books","category":"Overly restrictive choice","reason":"While science books use sub-headings, many other types of nonfiction like history books, biographies, and newspaper articles use them too."},"",{"choice":"Only in comic books","category":"Incorrect text type","reason":"Comic books use speech bubbles and panels to tell a story visually, but they rarely use traditional nonfiction sub-headings."}]},"studyAid":{"definition":"Sub-headings are small titles placed above sections of text to tell the reader what that specific part is about.","example":"A book about animals might use sub-headings like 'Where Mammals Live' or 'What Reptiles Eat' to organize the chapters.","strategyClue":"Think about whether the text is trying to teach you facts (nonfiction) or tell you a made-up story (fiction). Sub-headings are tools for organizing factual information.","link":"https://www.readingrockets.org/topics/comprehension/articles/using-text-features-support-comprehension","linkText":"Reading Rockets - Text Features"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["reference skills","research skills","text features"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"reference-skills-sub-heading","sequence":10,"skillIds":["reference-skills.reference-research"],"standardIds":["W.3-6.7-8"]}},{"id":"reference-skills-sub-heading-q0011","version":3,"contentHash":"sha256:489d941a84887d31f34d53f70cbea70d1f8a366a940db4ead22b7eb96a5dad61","question":"If you wanted to find information about 'volcanoes' in a geology chapter, what should you look for?","choices":["The table of contents only","A sub-heading about volcanoes","The author's name","The copyright date"],"correct":1,"explanation":{"correct":"Answer: A sub-heading about volcanoes. Sub-headings are specifically designed to break a chapter into smaller topics, making them the most direct way to locate information about a specific subject like volcanoes.","incorrect":[{"choice":"The table of contents only","category":"too broad of scope","reason":"The table of contents tells you which chapter covers geology, but it doesn't give you specific details about volcanoes inside that chapter."},"",{"choice":"The author's name","category":"irrelevant bibliographic information","reason":"Knowing who wrote the book tells you who created it, but it does not help you find specific facts about volcanoes within the text."},{"choice":"The copyright date","category":"irrelevant publication info","reason":"The copyright date tells you how old the book is, which doesn't help you navigate the internal organization of the chapter's topics."}]},"studyAid":{"definition":"Text features are organizational tools like sub-headings, sidebars, and captions that help readers find specific information quickly.","example":"Use a sub-heading for 'Types of Clouds' to find cloud facts; use an index for specific terms; use a glossary to define words.","strategyClue":"Ask yourself: 'Which feature helps me narrow down the topic to a specific section rather than just identifying the book as a whole?'","link":"https://www.readingrockets.org/topics/comprehension/articles/using-text-features-support-comprehension","linkText":"Reading Rockets - Text Features"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"extended-context","skills":["reference skills","research skills","text features"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"reference-skills-sub-heading","sequence":11,"skillIds":["reference-skills.reference-research"],"standardIds":["W.3-6.7-8"]}},{"id":"reference-skills-sub-heading-q0012","version":3,"contentHash":"sha256:d8c47121b2e2eb943ca885537a36a17b1ad6be22807f249e5487bfd38af24564","question":"Which would be a good sub-heading for a section about lion behavior?","choices":["Africa","Lions","How Lions Hunt","Mammals"],"correct":2,"explanation":{"correct":"Answer: How Lions Hunt. Sub-headings should describe the specific content of a paragraph or section. Since the section is about lion behavior, 'How Lions Hunt' clearly summarizes that action.","incorrect":[{"choice":"Africa","category":"too broad","reason":"While lions live in Africa, this is a place name, not an action or behavior. It does not explain what the reader will learn about what lions do."},{"choice":"Lions","category":"too general","reason":"This is simply the topic of the entire book or article. A sub-heading needs to be more specific to show that this particular part is about their behavior."},"",{"choice":"Mammals","category":"category label","reason":"This is a classification of animals. It describes what a lion is, but it doesn't describe the specific behaviors like hunting or socializing."}]},"studyAid":{"definition":"A sub-heading acts like a mini-title that tells the reader the main idea of a specific section of text.","example":"For a section about a bird building a nest, 'Building a Home' is a better sub-heading than just 'Birds'.","strategyClue":"Look at the sentences in the section you are describing. If the text explains how something is done or why it happens, choose a heading that sounds like a topic for a process or action.","link":"https://www.readingrockets.org/topics/comprehension/articles/using-text-features-support-comprehension","linkText":"Reading Rockets - Text Features"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["reference skills","research skills","text features"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"reference-skills-sub-heading","sequence":12,"skillIds":["reference-skills.reference-research"],"standardIds":["W.3-6.7-8"]}},{"id":"reference-skills-sub-heading-q0013","version":3,"contentHash":"sha256:c95ce7e0431b18ecbbceaa196e51e31ca819a101d02568be0a6d1f2c290a2c5b","question":"What usually comes right after a sub-heading?","choices":["A picture","A paragraph about that topic","The table of contents","A bibliography"],"correct":1,"explanation":{"correct":"Answer: A paragraph about that topic. A sub-heading acts like a mini-title that tells the reader the specific topic of the following section, so the paragraph underneath must match that topic.","incorrect":[{"choice":"A picture","category":"misplaced text feature","reason":"While pictures are often near sub-headings, they usually serve as illustrations for the text; the text itself provides the direct explanation of the sub-heading's topic."},"",{"choice":"The table of contents","category":"wrong structural location","reason":"The table of contents appears at the very beginning of a book or article to list section titles, not underneath every individual sub-heading."},{"choice":"A bibliography","category":"misplaced end matter","reason":"A bibliography lists sources used for research and is almost always found at the very end of a document, not immediately following a sub-heading."}]},"studyAid":{"definition":"A sub-heading acts as a signpost in a text, introducing a new section or a more specific part of the main topic.","example":"Main Topic: Insects. Sub-heading: 'Ants'. Following text: A paragraph about how ants live in colonies and work together.","strategyClue":"Ask yourself: 'What is this section supposed to be about?' Look for the text that provides information or details matching the specific title of that sub-heading.","link":"https://www.readingrockets.org/topics/comprehension/articles/using-text-features-support-comprehension","linkText":"Reading Rockets - Text Features"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["reference skills","research skills","text features"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"reference-skills-sub-heading","sequence":13,"skillIds":["reference-skills.reference-research"],"standardIds":["W.3-6.7-8"]}},{"id":"reference-skills-sub-heading-q0014","version":3,"contentHash":"sha256:428c16e39cf45753cf6ef86b77b6fd11694f9286140c314ff66da99f9da08d10","question":"Which text feature works WITH sub-headings to organize a book?","choices":["Table of contents","Index","Both A and B","None"],"correct":2,"explanation":{"correct":"Answer: Both A and B. The table of contents outlines the structure of the book by listing chapters, while sub-headings organize the content within those chapters. Together, they help the reader navigate and understand the flow of information.","incorrect":[{"choice":"Table of contents","category":"incomplete answer","reason":"While a table of contents organizes a book, an index also works alongside sub-headings by showing where specific topics appear. Both tools work together to make information easy to find."},{"choice":"Index","category":"incomplete answer","reason":"An index helps you find specific terms, but it is not the only feature that works with sub-headings. The table of contents provides the overall map of the book's organization."},"",{"choice":"None","category":"incorrect identification","reason":"Text features are specifically designed to organize information. Both the table of contents and the index help readers navigate the book's sections."}]},"studyAid":{"definition":"Text features are parts of a book, such as headings, tables of contents, and indexes, that help readers organize information and understand what they are reading.","example":"Table of contents: found at the front to list chapters. Sub-headings: found in the text to break up topics. Index: found at the back to list specific terms.","strategyClue":"Think about how you find information in a textbook. Ask yourself if the feature helps you see the 'big picture' of the chapters or find specific 'details' within the book.","link":"https://www.readingrockets.org/topics/comprehension/articles/using-text-features-support-comprehension","linkText":"Reading Rockets - Text Features"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["reference skills","research skills","text features"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"reference-skills-sub-heading","sequence":14,"skillIds":["reference-skills.reference-research"],"standardIds":["W.3-6.7-8"]}},{"id":"reference-skills-sub-heading-q0015","version":3,"contentHash":"sha256:a4d77d227c1fde3294e6b59335651aacabbf8016b5ffb4878db85ea7b876bfbb","question":"Why might an author use many sub-headings?","choices":["To make the book look longer","To help readers find and understand information","To confuse readers","To avoid writing full sentences"],"correct":1,"explanation":{"correct":"Answer: To help readers find and understand information. Sub-headings act like a map for a reader, breaking text into manageable sections and highlighting the main topic of each part.","incorrect":[{"choice":"To make the book look longer","category":"Incorrect purpose","reason":"Adding headings does not change the actual length of the content. Authors use headings to improve clarity, not to change the physical size of a book."},"",{"choice":"To confuse readers","category":"Incorrect purpose","reason":"The purpose of any text feature is to make reading easier, not harder. Headings are designed to guide the reader through the material."},{"choice":"To avoid writing full sentences","category":"Incorrect purpose","reason":"Sub-headings are usually short phrases, but their goal is to organize ideas, not to avoid writing complete sentences elsewhere in the text."}]},"studyAid":{"definition":"Sub-headings are titles used within a text to break it into smaller, organized sections. They help a reader know what each section will be about.","example":"In a report on animals, a sub-heading like 'What Do They Eat?' helps you find diet information quickly.","strategyClue":"Think about how you look for information in a textbook. Do you read every single word, or do you scan for labels that tell you where specific facts are hidden?","link":"https://www.readingrockets.org/topics/comprehension/articles/using-text-features-support-comprehension","linkText":"Reading Rockets - Text Features"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["reference skills","research skills","text features"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"reference-skills-sub-heading","sequence":15,"skillIds":["reference-skills.reference-research"],"standardIds":["W.3-6.7-8"]}},{"id":"reference-skills-sub-heading-q0016","version":3,"contentHash":"sha256:8f4d9e0cef99c1e59cbc1b1053922b2a3d1baed9d2ebfe0ed073096441d54b28","question":"Which topics would best complete the following outline? I. Sports equipment","choices":["cleated shoes","ice skates","bases","batting helmet"],"correct":2,"explanation":{"correct":"Answer: bases. An outline about 'sports equipment' should contain items used to play a game. Bases are essential pieces of equipment used on a baseball field to mark the path of play.","incorrect":[{"choice":"cleated shoes","category":"specific clothing item","reason":"While often worn by athletes, cleated shoes are categorized as footwear or apparel rather than pieces of field equipment used to define the sport's layout."},{"choice":"ice skates","category":"category mismatch","reason":"This item belongs to the sport of ice hockey or skating; while they are equipment, the outline implies a specific set. Without more context, 'bases' fits the general theme of field-based sports equipment better."},"",{"choice":"batting helmet","category":"personal protective gear","reason":"A batting helmet is considered safety or protective gear. In an outline about 'sports equipment,' items like bases are more foundational to the game's setup than player-worn protection."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["reference skills","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"reference-skills-sub-heading","sequence":16,"sourceFile":"Advanced-1_language Usage.pdf","sourceQuestionNumber":39,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reference-skills.reference-research"],"standardIds":["W.3-6.7-8"]},"studyAid":{"definition":"An outline topic should be a specific item that fits logically within the main category provided.","example":"Category: Kitchen Tools. Good items: Spatula, Whisk, Ladle. Bad items: Refrigerator (it is an appliance), Chicken (it is an ingredient).","strategyClue":"Ask yourself if the item is a tool or object needed to physically set up or play the activity described in the main heading.","link":"","linkText":""}},{"id":"reference-skills-sub-heading-q0017","version":3,"contentHash":"sha256:7dac92eafb2eff7519277fe9316c7a2b06e36de5fa2d71f60afe0c9a37337789","question":"Choose the best main topic for the words listed below. programs, touch, battery, video","choices":["My New Television","My New Stove","My New Lawnmower","My New Computer"],"correct":3,"explanation":{"correct":"Answer: My New Computer. The words 'programs,' 'touch,' 'battery,' and 'video' are all features or components commonly found on a modern laptop or desktop computer.","incorrect":[{"choice":"My New Television","category":"mismatched item features","reason":"While a TV can have video, it does not typically have 'programs' (in the software sense) or a battery, and most traditional TVs do not have a touch screen as a primary feature."},{"choice":"My New Stove","category":"mismatched item features","reason":"A stove is a kitchen appliance used for cooking. It does not use computer programs or display video, and it is not powered by a portable battery."},{"choice":"My New Lawnmower","category":"mismatched item features","reason":"A lawnmower is a tool used for outdoor chores. It does not contain software programs, touchscreens, or video players."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["reference skills","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"reference-skills-sub-heading","sequence":17,"sourceFile":"Advanced-2_language Usage.pdf","sourceQuestionNumber":26,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reference-skills.reference-research"],"standardIds":["W.3-6.7-8"]},"studyAid":{"definition":"A main topic represents the common category or theme that connects a group of words together.","example":"Topic: School Supplies. Words: pencil, eraser, notebook, ruler.","strategyClue":"Look at each word in the list and ask yourself, 'Where would I find this?' or 'What machine uses this part?' Eliminate choices that don't include all of the listed items.","link":"","linkText":""}},{"id":"reference-skills-sub-heading-q0018","version":3,"contentHash":"sha256:6df914f402409a5705c036f3dfcdae124e4f213314af25fa5b9dedada636cf4d","question":"Which one would be the main topic in an outline?","choices":["Glacier","Red Woods","National Parks","Mount Rushmore"],"correct":2,"explanation":{"correct":"Answer: National Parks. A main topic represents the broad category that encompasses other smaller details. 'National Parks' is the overarching group that contains the other options as specific examples.","incorrect":[{"choice":"Glacier","category":"specific sub-topic","reason":"Glacier is a specific location, not a broad category. It fits as a sub-point under the main topic of National Parks."},{"choice":"Red Woods","category":"specific sub-topic","reason":"Red Woods is a specific park site. In an outline, this would be a detail supporting the broader main topic."},"",{"choice":"Mount Rushmore","category":"specific sub-topic","reason":"Mount Rushmore is a specific monument or landmark. Like the others, it is too narrow to serve as the main topic for a group that includes various parks."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["reference skills","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"reference-skills-sub-heading","sequence":18,"sourceFile":"Basic-1_Writing strategies_Application_Style.pdf","sourceQuestionNumber":2,"sourceCategory":"writing-strategies-application-style","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reference-skills.reference-research"],"standardIds":["W.3-6.7-8"]},"studyAid":{"definition":"A main topic is the big, general idea that covers all the smaller details or examples listed under it in an outline.","example":"Main Topic: Fruit | Sub-topics: Apple, Banana, Pear. Main Topic: Planets | Sub-topics: Mars, Earth, Jupiter.","strategyClue":"Ask yourself, 'Could all the other options fit inside this choice as examples?' If they can, you have found the category that acts as the main topic.","link":"","linkText":""}},{"id":"reference-skills-sub-heading-q0019","version":3,"contentHash":"sha256:da5d09d06256173e1c1e8f245edc3c73db80fb031eccbf0a94183f716acf9543","question":"Which of the following would be a sub-heading in an outline about pets?","choices":["dogs","shoes","flowers","rocks"],"correct":0,"explanation":{"correct":"Answer: dogs. An outline about pets should include categories or types of animals people keep, and 'dogs' is a common type of pet.","incorrect":["",{"choice":"shoes","category":"category mismatch","reason":"Shoes are clothing items, not living animals. Including them in an outline about pets would be confusing because they do not fit the main topic."},{"choice":"flowers","category":"category mismatch","reason":"Flowers are plants, not pets. While you can care for plants, they belong in a different category than animals kept for companionship."},{"choice":"rocks","category":"category mismatch","reason":"Rocks are non-living objects. Since a pet is a living creature that you care for, rocks do not belong in this outline."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["reference skills","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"reference-skills-sub-heading","sequence":19,"sourceFile":"Basic-1_Writing strategies_Application_Style.pdf","sourceQuestionNumber":8,"sourceCategory":"writing-strategies-application-style","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reference-skills.reference-research"],"standardIds":["W.3-6.7-8"]},"studyAid":{"definition":"An outline sub-heading must be a specific example that falls under the main topic's umbrella.","example":"Main Topic: Sports -> Sub-headings: Soccer, Basketball, Swimming. Main Topic: Fruit -> Sub-headings: Apples, Bananas, Grapes.","strategyClue":"Ask yourself: 'Is this item a type of the main topic?' If it is not a direct example of the main subject, it belongs in a different outline.","link":"","linkText":""}},{"id":"reference-skills-sub-heading-q0020","version":3,"contentHash":"sha256:9a8d00407d407144de1e44d16d57946aeaa2ecdff00d043ff85e0a7c7031e3fd","question":"Choose the best main topic for the words listed below. hiking, animal tracks, flowers, logs","choices":["My Backpack","My Scrapbook","My Pet Animal","My Nature Walk"],"correct":3,"explanation":{"correct":"Answer: My Nature Walk. Hiking, animal tracks, flowers, and logs are all things commonly seen or experienced while walking outdoors in nature.","incorrect":[{"choice":"My Backpack","category":"category too narrow","reason":"While you might carry a backpack on a hike, 'flowers' and 'logs' are not items kept inside a backpack. This title doesn't fit all the words in the list."},{"choice":"My Scrapbook","category":"broad topic mismatch","reason":"A scrapbook could contain pictures of many different things, but the items listed are specifically related to an outdoor excursion rather than a collection of memories."},{"choice":"My Pet Animal","category":"incorrect specific subject","reason":"'Animal tracks' might involve animals, but 'hiking,' 'flowers,' and 'logs' do not describe a pet. This title is too specific to one part of the list."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["reference skills","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"reference-skills-sub-heading","sequence":20,"sourceFile":"Basic-1_language Usage.pdf","sourceQuestionNumber":27,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reference-skills.reference-research"],"standardIds":["W.3-6.7-8"]},"studyAid":{"definition":"A main topic is the big idea that connects all the smaller items in a list or group.","example":"List: pencil, eraser, ruler. Topic: School Supplies. List: dog, cat, hamster. Topic: Common Pets.","strategyClue":"Try to find the one category that acts as a 'container' for every single word in the list. If one word feels left out or doesn't fit, it is likely not the correct main topic.","link":"","linkText":""}},{"id":"reference-skills-sub-heading-q0021","version":3,"contentHash":"sha256:956e9b21743c25547d93940016a8acaf7e20f10bbbc522d9fd7f9c5ccaa2ce60","question":"Choose the best main topic for the words listed below. machines, warehouses, jobs, trucks","choices":["My Trip to the Zoo","My Trip to the Farm","My Trip to the Factory","My Trip to the Airport"],"correct":2,"explanation":{"correct":"Answer: My Trip to the Factory. These words—machines, warehouses, jobs, and trucks—are all commonly associated with industrial work and manufacturing, which takes place in a factory.","incorrect":[{"choice":"My Trip to the Zoo","category":"mismatched topic category","reason":"At a zoo, you would expect to find animals and exhibits, not machines, warehouses, or trucks."},{"choice":"My Trip to the Farm","category":"mismatched topic category","reason":"While farms use some machines, they typically feature crops, livestock, and barns rather than industrial warehouses or factory jobs."},"",{"choice":"My Trip to the Airport","category":"mismatched topic category","reason":"Airports are centered around airplanes, passengers, and runways, which do not align with the category of factory-based machinery and industrial jobs."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["reference skills","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"reference-skills-sub-heading","sequence":21,"sourceFile":"Proficient-2_language Usage.pdf","sourceQuestionNumber":26,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reference-skills.reference-research"],"standardIds":["W.3-6.7-8"]},"studyAid":{"definition":"A main topic represents the shared theme that connects a group of words together.","example":"Group: spoon, fork, plate (Topic: Dining supplies); Group: rain, snow, sun (Topic: Weather)","strategyClue":"Imagine you are drawing a picture for each word on the list; pick the setting where all of those items would realistically be found together.","link":"","linkText":""}},{"id":"reference-skills-sub-heading-q0022","version":3,"contentHash":"sha256:3bc7794d706999a61b8fb163deaebc6e9d97723d52e1a6eafea77594e1581693","question":"Read the following topics. Paint brushes Water colors Art class Charcoal pencils Pen and ink Easels Which would be the main topic on an outline?","choices":["Wat er colors","Charcoal pencils","Pen and ink","Art class"],"correct":3,"explanation":{"correct":"Answer: Art class. An outline main topic should be a broad category that covers all the other items, and 'Art class' is the central theme that includes painting, drawing, and supplies.","incorrect":[{"choice":"Wat er colors","category":"too specific","reason":"Water colors are a type of painting supply used in an art class. This is a supporting detail rather than the main category."},{"choice":"Charcoal pencils","category":"too specific","reason":"Charcoal pencils are a type of drawing tool found in an art class. A main topic should be general enough to include this tool."},{"choice":"Pen and ink","category":"too specific","reason":"Pen and ink is a specific medium. Like the other options, it belongs as a sub-topic under the broader category of an art class."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"passage-context","skills":["reference skills","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"reference-skills-sub-heading","sequence":22,"sourceFile":"Proficient-4_Writing strategies_Application_Style.pdf","sourceQuestionNumber":10,"sourceCategory":"writing-strategies-application-style","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["reference-skills.reference-research"],"standardIds":["W.3-6.7-8"]},"studyAid":{"definition":"A main topic in an outline is a broad category that covers all the specific details or sub-topics listed beneath it.","example":"Main Topic: Sports. Sub-topics: Soccer, Basketball, Tennis. Main Topic: Fruit. Sub-topics: Apples, Bananas, Grapes.","strategyClue":"Look at each list item and ask, 'Could this be a bucket that holds the others?' If an item is just one specific example, it cannot be the main topic.","link":"","linkText":""}}],"metadata":{"gradesSupported":[3,4,5,6],"difficultiesSupported":["easy","medium","hard"],"selectorPolicy":"grade+difficulty selects exact matches first, then nearby grade-appropriate practice to fill the configured mission length"}}}
  );
})();
